  function pm1(B1, B2, base) {
    let a = modpow(BigInt(base), buildE(B1), n);
    let g = gcd(a - 1n, n);
    let r = report(g); if (r) return r;
    if (g === n) return null;
    const ps = [];
    for (const p of PRIMES) { if (p > B1) { if (p > B2) break; ps.push(p); } }
    if (!ps.length) return null;
    let maxd = 0;
    for (let i = 1; i < ps.length; i++) { const d = ps[i] - ps[i - 1]; if (d > maxd) maxd = d; }
    const a2 = a * a % n;
    const powd = [1n];
    for (let d = 2; d <= maxd; d += 2) powd.push(powd[powd.length - 1] * a2 % n);
    let cur = modpow(a, BigInt(ps[0]), n);
    g = gcd(cur - 1n, n); r = report(g); if (r) return r;
    let acc = 1n;
    for (let i = 1; i < ps.length; i++) {
      cur = cur * powd[(ps[i] - ps[i - 1]) >> 1] % n;
      acc = acc * (cur - 1n) % n;
      if ((i & 63) === 0) {
        g = gcd(acc, n); r = report(g); if (r) return r;
        if (g === n) return null;
