  function pp1(B1, x) {
    const E = buildE(B1);
    const bits = E.toString(2);
    let vk = x % n;
    let vk1 = (x * x - 2n) % n;
    for (let i = 1; i < bits.length; i++) {
      const t = (vk * vk1 - x) % n;
      if (bits.charCodeAt(i) === 48) { const u = (vk * vk - 2n) % n; vk1 = t; vk = u; }
      else { const u = (vk1 * vk1 - 2n) % n; vk = t; vk1 = u; }
      if ((i & 32767) === 0 && now() > BUDGET) return null;
    }
    return report(gcd(vk - 2n, n));
  }

  let r;
  r = pm1(100000, 2000000, 2); if (r) return r;
  r = pm1(100000, 2000000, 3); if (r) return r;
  for (const x of [3n, 4n, 5n, 6n, 7n, 9n, 11n, 13n]) {
    if (now() > 200) break;
    r = pp1(50000, x); if (r) return r;
  }
  if (now() < BUDGET) { r = pm1(300000, 4000000, 2); if (r) return r; }
  if (now() < BUDGET) { r = pm1(300000, 4000000, 3); if (r) return r; }
  for (const x of [3n, 4n, 5n, 6n]) {
    if (now() > BUDGET) break;
    r = pp1(200000, x); if (r) return r;
  }

