  function brent(nn) {
    if (nn % 2n === 0n) return 2n;
    let c = 1n;
    while (now() < BUDGET) {
      let y = 2n, g = 1n, rr = 1n, q = 1n, x = 2n, ys = 2n;
      while (g === 1n && now() < BUDGET) {
        x = y;
        for (let i = 0; i < rr; i++) y = (y * y + c) % nn;
        let k = 0n;
        while (k < rr && g === 1n) {
          ys = y;
          const m = (rr - k < 128n) ? rr - k : 128n;
          for (let i = 0; i < m; i++) { y = (y * y + c) % nn; q = q * (x < y ? y - x : x - y) % nn; }
          g = gcd(q, nn);
          k += m;
        }
        rr *= 2n;
      }
      if (g === nn) {
        g = 1n;
        let y2 = ys;
        while (g === 1n && now() < BUDGET) { y2 = (y2 * y2 + c) % nn; g = gcd(x < y2 ? y2 - x : x - y2, nn); }
      }
      if (g > 1n && g < nn) return g;
      c += 1n;
    }
    return null;
  }
  const g = brent(n);
  if (g) { const res = report(g); if (res) return res; }

  return null;
}
