    if (q > 1000000000000n) return null; // infeasible prime factor
    let qe = 1n;
    for (let i = 0; i < e; i++) qe *= q;
    const alpha = modpow(g, ord / qe, p);
    const beta = modpow(h, ord / qe, p);
    const gamma = modpow(alpha, qe / q, p);
    let xk = 0n;
    for (let k = 0n; k < BigInt(e); k++) {
