    if (v < 2n) return v;
    let x = BigInt(Math.floor(Math.sqrt(Number(v)))) + 1n;
    while (true) {
      const y = (x + v / x) >> 1n;
      if (y >= x) break;
      x = y;
    }
    while (x * x > v) x -= 1n;
    while ((x + 1n) * (x + 1n) <= v) x += 1n;
    return x;
  }
  function finish(f) {
    let p = f, q = N / f;
    if (p > q) { const t = p; p = q; q = t; }
    return [p.toString(), q.toString()];
  }

  // trial division
  const LIM = 100000;
  const comp = new Uint8Array(LIM + 1);
  for (let i = 2; i <= LIM; i++) {
    if (!comp[i]) {
      const P = BigInt(i);
      if (P * P > N) break;
      if (N % P === 0n) return finish(P);
      for (let j = i * i; j <= LIM; j += i) comp[j] = 1;
    }
  }

