  {
    let a = isqrt(N);
    if (a * a < N) a += 1n;
    for (let i = 0; i < 200000; i++) {
      const b2 = a * a - N;
      const b = isqrt(b2);
      if (b * b === b2) return finish(a - b);
      a += 1n;
      if ((i & 255) === 0 && up()) break;
    }
  }

