      if (comp[i]) continue;
      let pe = i;
      while (pe * i <= 100000) pe *= i;
      a = modpow(a, BigInt(pe), N);
      if ((i & 63) === 1) {
        const g = gcd(a - 1n, N);
        if (g > 1n && g < N) return finish(g);
        if (g === N) break;
      }
    }
    const g = gcd(a - 1n, N);
    if (g > 1n && g < N) return finish(g);
  }

  function modpow(b, e, m) {
    let r = 1n; b %= m;
    while (e > 0n) {
      if (e & 1n) r = r * b % m;
      b = b * b % m;
      e >>= 1n;
    }
    return r;
  }

  // Brent's rho
  function brent(n, c) {
    if (n % 2n === 0n) return 2n;
    let x = 2n, y = 2n, g = 1n, r = 1n, q = 1n, ys = y;
    const m = 128n;
